def binidx(q,n=12):
    e=np.quantile(q,np.linspace(0,1,n+1)); e[-1]+=1e-9
    return np.clip(np.searchsorted(e,q,side='right')-1,0,n-1), e
def rank1_fit(a,b,target):
    ia,ea=binidx(a); ib,eb=binidx(b)
    # fit target ~ F[ia]*G[ib] via ALS, using a 2D table of means where data exist (use full model: additive interactions)
    n=12
    F=np.ones(n); G=np.ones(n)
    for it in range(200):
        for i in range(n):
            m=ia==i
            if m.sum(): F[i]=np.sum(target[m]*G[ib[m]])/np.sum(G[ib[m]]**2+1e-12)
        for j in range(n):
            m=ib==j
            if m.sum(): G[j]=np.sum(target[m]*F[ia[m]])/np.sum(F[ia[m]]**2+1e-12)
    pred=F[ia]*G[ib]
    # best linear scale on pred plus constant
    M=np.column_stack([np.ones_like(pred),pred]); cc,_,_,_=np.linalg.lstsq(M,target,rcond=None)
    rr=target-M@cc
    return np.mean(rr**2)/np.var(target),F,G
